<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue'
import { NButton,NInput,NDrawer,NDrawerContent,NSelect,NCheckbox } from 'naive-ui'
import { api,post,rows,ident,name,state,field,str,pretty,bytes,message,cookieToken,type Row } from '../api'
import { t,localized,renderText,formatDateTime,formatNumber,displayState } from '../i18n'
import Notice from '../components/Notice.vue'
import AppIcon from '../components/AppIcon.vue'
import FormDialog,{type FormField} from '../components/FormDialog.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
const props=defineProps<{kind:string}>(),emit=defineEmits<{navigate:[key:string]}>()
const credentials=ref<Row[]>([]),mounts=ref<Row[]>([]),items=ref<Row[]>([]),error=ref<unknown>(''),busy=ref(false),query=ref(''),page=ref(1),total=ref(0),detail=ref<Row|null>(null),selected=ref(''),tab=ref('overview'),feedback=ref<unknown>('')
const form=ref(false),formTitle=ref<unknown>(''),formDescription=ref<unknown>(''),fields=ref<FormField[]>([]),submitForm=ref<(v:Row)=>Promise<unknown>>(async()=>{}),confirm=ref(false),confirmTitle=ref<unknown>(''),confirmDetail=ref<unknown>(''),confirmAction=ref<()=>Promise<void>>(async()=>{}),actionBusy=ref(false)
const configMode=ref('form'),configValues=ref<Row>({}),configEnabled=ref<Record<string,boolean>>({}),configFields=[{key:'image',label:localized('resources.imageRef'),hint:localized('resources.imageHint')},{key:'env',label:localized('resources.environment'),hint:localized('resources.envHint')},{key:'cmd',label:localized('resources.commandArgs'),hint:localized('resources.cmdHint')},{key:'memory',label:localized('resources.memory'),hint:localized('resources.unlimitedHint')},{key:'nano_cpus',label:localized('resources.cpu'),hint:localized('resources.cpuHint')},{key:'restart_policy',label:localized('resources.restartPolicy'),hint:'no / always / unless-stopped / on-failure'}],logs=ref(''),tail=ref('200'),timestamps=ref(true),streaming=ref(false),terminal=ref(''),command=ref(''),shell=ref('/bin/sh'),stats=ref<Row>({}),preview=ref<Row|null>(null),configText=ref('{}'),resourceStats=ref<unknown>(''),terminalStatus=ref('')
let events:EventSource|undefined,ws:WebSocket|undefined,statsTimer:ReturnType<typeof setInterval>|undefined
const base=computed(()=>`/hosts/local/${props.kind}`),filtered=computed(()=>items.value.filter(row=>`${name(row)} ${ident(row)} ${str(row.Image)}`.toLowerCase().includes(query.value.toLowerCase())))
const inspectedResource=computed(()=>{if(!detail.value)return null;const wrapped=props.kind==='volumes'?detail.value.volume:props.kind==='images'?detail.value.image:undefined;return wrapped&&typeof wrapped==='object'?wrapped as Row:detail.value})
const titles=computed<Record<string,string>>(()=>({containers:t('resources.containers'),images:t('resources.images'),networks:t('resources.networks'),volumes:t('resources.volumes')}))
const tabs=['overview','config','logs','terminal','stats','data']
async function load(){busy.value=true;error.value='';try{const result=await api(`${base.value}?page=${page.value}&page_size=30`);items.value=rows(result);total.value=Number(result.total??items.value.length);if(props.kind==='images')credentials.value=rows(await api('/registry-credentials'));if(props.kind==='volumes')mounts.value=rows(await api('/hosts/local/mounts'))}catch(e){error.value=e}finally{busy.value=false}}
function showForm(title:unknown,f:FormField[],fn:(v:Row)=>Promise<unknown>,description:unknown=''){formTitle.value=title;fields.value=f;submitForm.value=fn;formDescription.value=description;form.value=true}
function danger(title:unknown,text:unknown,fn:()=>Promise<void>){error.value='';confirmTitle.value=title;confirmDetail.value=text;confirmAction.value=fn;confirm.value=true}
async function execute(){actionBusy.value=true;try{await confirmAction.value();confirm.value=false;feedback.value=localized('resources.submittedTasks');await load()}catch(e){error.value=e}finally{actionBusy.value=false}}
async function action(row:Row,op:string){danger(localized(`resources.${op}Container`),localized('resources.containerActionRisk',{name:name(row),id:ident(row)}),async()=>{await post(`${base.value}/${encodeURIComponent(ident(row))}/${op}`)})}
async function remove(row:Row){let references='';if(props.kind==='images'){try{const inspection=await api(`${base.value}/${encodeURIComponent(ident(row))}`);references=pretty(inspection.containers??inspection.references??[])}catch(e){error.value=e;return}}danger(localized(`resources.delete_${props.kind}`),localized(props.kind==='images'?'resources.deleteImageRisk':'resources.deleteRisk',{name:name(row),id:ident(row),references}),async()=>{await api(`${base.value}/${encodeURIComponent(ident(row))}`,{method:'DELETE',body:JSON.stringify({confirmed:true})});detail.value=null})}
async function inspect(row:Row){closeStreams();detail.value=null;configText.value='{}';configValues.value={};configEnabled.value={};configMode.value='form';error.value='';selected.value=ident(row);tab.value='overview';preview.value=null;try{detail.value=await api(`${base.value}/${encodeURIComponent(selected.value)}`)}catch(e){error.value=e}}
function closeStreams(){events?.close();events=undefined;ws?.close();ws=undefined;clearInterval(statsTimer);streaming.value=false}
function closeDetail(){detail.value=null;closeStreams()}
function startLogs(){events?.close();logs.value='';streaming.value=true;events=new EventSource(`/api/v1${base.value}/${encodeURIComponent(selected.value)}/logs?tail=${encodeURIComponent(tail.value)}&timestamps=${timestamps.value}&follow=true`);const append=(e:MessageEvent)=>{let line=e.data;try{const d=JSON.parse(line) as Row;line=str(d.text??d.message??d.line??d.log??line)}catch{}logs.value=(logs.value+line+'\n').slice(-150000)};events.onmessage=append;events.addEventListener('log',append as EventListener);events.addEventListener('stream-error',()=>{streaming.value=false});events.onerror=()=>{streaming.value=false};events.onopen=()=>{streaming.value=true}}
function connectTerminal(){ws?.close();terminal.value='';terminalStatus.value='';const socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/api/v1${base.value}/${encodeURIComponent(selected.value)}/terminal?shell=${encodeURIComponent(shell.value)}&csrf_token=${encodeURIComponent(cookieToken())}`);ws=socket;socket.binaryType='arraybuffer';socket.onopen=()=>socket.send(JSON.stringify({type:'resize',rows:24,cols:80}));ws.onmessage=e=>{const text=e.data instanceof ArrayBuffer?new TextDecoder().decode(e.data):String(e.data);terminal.value=(terminal.value+text).slice(-150000)};ws.onerror=()=>{if(ws===socket)terminalStatus.value='terminalFailed'};ws.onclose=()=>{if(ws===socket)terminalStatus.value=terminalStatus.value==='terminalFailed'?'terminalFailed':'terminalClosed'}}
function sendCommand(){if(ws?.readyState===WebSocket.OPEN){ws.send(command.value+'\r');command.value=''}}
async function readStats(){try{stats.value=await api(`${base.value}/${encodeURIComponent(selected.value)}/stats`)}catch(e){resourceStats.value=e}}
function switchTab(value:string){tab.value=value;if(value==='logs')startLogs();else if(value==='stats'){void readStats();statsTimer=setInterval(readStats,3000)}else{events?.close();clearInterval(statsTimer)}}
function ports(row:Row){return rows(row.Ports).map(p=>`${str(p.IP??'')} ${p.PublicPort?`${str(p.PublicPort)} → `:''}${str(p.PrivatePort)}/${str(p.Type)}`).join(', ')||'—'}
function project(row:Row){return str((row.Labels as Row|undefined)?.['com.docker.compose.project'])}
function pull(){showForm(localized('resources.pullImage'),[{key:'image',label:localized('resources.imageRef'),required:true,placeholder:localized('resources.imagePlaceholder')},{key:'credential_id',label:localized('resources.registryCredential'),type:'select',options:[{label:localized('resources.anonymousPull'),value:''},...credentials.value.map(c=>({label:name(c),value:ident(c)}))]},{key:'platform',label:localized('resources.platform'),placeholder:localized('resources.platformPlaceholder')}],v=>post('/hosts/local/images/pull',v),localized('resources.pullDescription'))}
function credential(){showForm(localized('resources.saveCredential'),[{key:'name',label:localized('resources.credentialName'),required:true},{key:'server',label:localized('resources.registryAddress'),required:true,placeholder:'https://index.docker.io/v1/'},{key:'username',label:localized('resources.username'),required:true},{key:'password',label:localized('resources.password'),type:'password',required:true}],v=>post('/registry-credentials',v),localized('resources.credentialDescription'))}
async function importImage(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy.value=true;try{await api('/hosts/local/images/import',{method:'POST',body:file});feedback.value=localized('resources.imageImported');await load()}catch(e){error.value=e}finally{busy.value=false}}
function create(){const f:FormField[]=[{key:'name',label:localized('resources.name'),required:true},{key:'driver',label:localized('resources.driver'),initial:props.kind==='networks'?'bridge':'local',required:true}];if(props.kind==='networks')f.push({key:'internal',label:localized('resources.internalNetwork'),type:'checkbox'});showForm(localized(`resources.create_${props.kind}`),f,v=>post(base.value,v))}
async function testCredential(row:Row){try{const result=await post(`/registry-credentials/${ident(row)}/test`);feedback.value=localized('resources.authSuccess',{status:str(result.status)})}catch(e){error.value=e}}
function removeCredential(row:Row){danger(localized('resources.deleteCredential'),localized('resources.deleteCredentialRisk',{name:name(row)}),async()=>{await api(`/registry-credentials/${ident(row)}`,{method:'DELETE',body:JSON.stringify({confirmed:true})})})}
function scan(){showForm(localized('resources.scanDirectorySize'),[{key:'path',label:localized('resources.authorizedPath'),required:true}],v=>post('/hosts/local/storage/scan',v),localized('resources.scanDescription'))}
function configChanges():Row{if(configMode.value==='json')return JSON.parse(configText.value) as Row;const value:Row={};for(const f of configFields){if(!configEnabled.value[f.key])continue;const text=String(configValues.value[f.key]??'');if(f.key==='env'||f.key==='cmd')value[f.key]=text?text.split('\n'):[];else if(f.key==='memory'||f.key==='nano_cpus'){const number=Number(text);if(!Number.isFinite(number)||number<0)throw localized(`resources.invalid_${f.key}`);value[f.key]=Math.round(number*(f.key==='memory'?1024**2:1e9))}else if(f.key==='restart_policy')value[f.key]={Name:text,MaximumRetryCount:0};else value[f.key]=text;}return value}
async function previewConfig(){try{const changes=configChanges();preview.value=await post(`${base.value}/${encodeURIComponent(selected.value)}/config/preview`,{changes})}catch(e){error.value=e}}
function applyConfig(){danger(localized('resources.applyConfig'),localized('resources.applyConfigRisk'),async()=>{await post(`${base.value}/${encodeURIComponent(selected.value)}/config`,{fingerprint:preview.value?.fingerprint,confirmed:true,changes:configChanges()});preview.value=null})}
function linkedResource(kind:string,id:string){sessionStorage.setItem('docker-manager:inspect',JSON.stringify({kind,id}));closeDetail();emit('navigate',kind)}
onMounted(async()=>{await load();const pending=sessionStorage.getItem('docker-manager:inspect');if(pending){const value=JSON.parse(pending) as {kind:string;id:string};if(value.kind===props.kind){sessionStorage.removeItem('docker-manager:inspect');await inspect({id:value.id})}}});onUnmounted(closeStreams)
</script>
<template><div class="toolbar"><n-input v-model:value="query" :placeholder="t('resources.searchPlaceholder')" class="search" :input-props="{'aria-label':t('resources.searchResources')}" clearable/><div class="actions"><n-button @click="load" :loading="busy"><AppIcon name="refresh"/>{{ t('resources.refresh') }}</n-button><template v-if="kind==='images'"><n-button @click="credential">{{ t('resources.registryCredential') }}</n-button><label class="file-button">{{ t('resources.importTar') }}<input type="file" accept=".tar" @change="importImage"></label><n-button type="primary" @click="pull"><AppIcon name="plus"/>{{ t('resources.pullImage') }}</n-button></template><template v-if="['networks','volumes'].includes(kind)"><n-button v-if="kind==='volumes'" @click="scan">{{ t('resources.scanDirectory') }}</n-button><n-button type="primary" @click="create"><AppIcon name="plus"/>{{ t(`resources.create_${kind}`) }}</n-button></template></div></div><p v-if="feedback" class="notice success" role="status">{{ renderText(feedback) }} <button @click="emit('navigate','tasks')">{{ t('resources.viewTasks') }}</button></p><Notice :error="error" :busy="busy"/><section class="panel table-panel"><div class="panel-title"><h3>{{ t('resources.localResources',{kind:titles[kind]??kind}) }} <span class="count">{{ error?'—':formatNumber(total) }}</span></h3><span class="eyebrow">{{ t('resources.liveInventory') }}</span></div><div class="table-scroll"><table class="resource-table" :class="`resource-table-${kind}`"><thead><tr><th>{{ t('resources.nameId') }}</th><th>{{ kind==='containers'?t('resources.images'):kind==='images'?t('resources.size'):t('resources.driver') }}</th><th>{{ kind==='containers'?t('resources.status'):t('resources.details') }}</th><th v-if="kind==='containers'">{{ t('resources.portsCompose') }}</th><th v-if="kind==='images'">Digest</th><th v-if="kind==='networks'">{{ t('resources.subnetGateway') }}</th><th class="align-right">{{ t('resources.actions') }}</th></tr></thead><tbody><tr v-for="row in filtered" :key="ident(row)"><td><button class="resource-name" :title="name(row)" @click="inspect(row)">{{ name(row) }}</button><code>{{ ident(row).slice(0,24) }}</code></td><td>{{ kind==='containers'?str(row.Image):kind==='images'?bytes(row.Size):str(row.Driver) }}</td><td><span v-if="kind==='containers'" class="tag" :class="state(row).toLowerCase()">{{ displayState(state(row)) }}</span><span v-else>{{ str(field(row,'Scope','Mountpoint','Created','RepoDigests')) }}</span></td><td v-if="kind==='containers'"><span>{{ ports(row) }}</span><button v-if="project(row)!=='—'" class="resource-name" @click="emit('navigate','compose')">{{ project(row) }} ↗</button><code>{{ typeof row.Created==='number'?formatDateTime(row.Created*1000):'—' }}</code></td><td v-if="kind==='images'"><code>{{ str(row.RepoDigests) }}</code></td><td v-if="kind==='networks'"><code>{{ str((row.IPAM as Row|undefined)?.Config) }}</code></td><td><div class="row-actions"><template v-if="kind==='containers'"><n-button size="small" @click="action(row,state(row)==='running'?'stop':'start')">{{ state(row)==='running'?t('resources.stop'):t('resources.start') }}</n-button><n-button size="small" @click="action(row,'restart')">{{ t('resources.restart') }}</n-button></template><n-button size="small" @click="inspect(row)">{{ t('resources.details') }}</n-button><n-button size="small" quaternary type="error" @click="remove(row)">{{ t('resources.delete') }}</n-button></div></td></tr></tbody></table></div><Notice :empty="!busy&&!error&&!filtered.length"/><div class="pagination"><span>{{ t('resources.pagination',{page:formatNumber(page),total:formatNumber(total)}) }}</span><div class="actions"><n-button size="small" :disabled="page<=1" @click="page--;load()">{{ t('resources.previous') }}</n-button><n-button size="small" :disabled="page*30>=total" @click="page++;load()">{{ t('resources.next') }}</n-button></div></div></section><section v-if="kind==='images'" class="panel table-panel section-gap"><div class="panel-title"><h3>{{ t('resources.registryCredential') }} <span class="count">{{ formatNumber(credentials.length) }}</span></h3><span class="eyebrow">{{ t('resources.encryptedCredentials') }}</span></div><div v-for="item in credentials" :key="ident(item)" class="repository-row"><div><strong>{{ name(item) }}</strong><code>{{ str(item.server) }} · {{ str(item.username) }}</code></div><div class="actions"><n-button size="small" @click="testCredential(item)">{{ t('resources.testAuth') }}</n-button><n-button size="small" type="error" @click="removeCredential(item)">{{ t('resources.delete') }}</n-button></div></div><Notice :empty="!credentials.length"/></section><section v-if="kind==='volumes'" class="panel section-gap"><div class="panel-title"><h3>{{ t('resources.containerMounts') }}</h3><span class="eyebrow">{{ t('resources.bindMountsVolumes') }}</span></div><div class="table-scroll"><table v-if="mounts.length"><thead><tr><th>{{ t('resources.containers') }}</th><th>{{ t('resources.mountTypePath') }}</th><th>{{ t('resources.containerPath') }}</th><th>{{ t('resources.volumes') }}</th></tr></thead><tbody><tr v-for="(entry,i) in mounts" :key="i"><td><button class="resource-name" @click="linkedResource('containers',str(entry.container_id))">{{ str(entry.names) }}</button></td><td>{{ str((entry.mount as Row).Type) }}<code>{{ str((entry.mount as Row).Source) }}</code></td><td>{{ str((entry.mount as Row).Destination) }}</td><td><button v-if="(entry.mount as Row).Name" class="resource-name" @click="inspect({id:str((entry.mount as Row).Name)})">{{ str((entry.mount as Row).Name) }}</button><span v-else>{{ t('resources.bindMount') }}</span></td></tr></tbody></table></div><Notice :empty="!mounts.length"/></section><p v-if="kind==='volumes'" class="footnote">{{ t('resources.volumeWarning') }}</p><n-drawer :show="Boolean(detail)" :width="'min(850px, 100vw)'" @update:show="value=>!value&&closeDetail()"><n-drawer-content :title="inspectedResource?name(inspectedResource):t('resources.resourceDetails')" closable><div v-if="detail"><Notice :error="error"/><div v-if="kind==='containers'" class="tabs"><button v-for="item in tabs" :key="item" :class="{active:tab===item}" @click="switchTab(item)">{{ t(`resources.${item}`) }}</button></div><template v-if="tab==='logs'"><div class="toolbar"><n-input v-model:value="tail" :placeholder="t('resources.tailLines')"/><n-checkbox v-model:checked="timestamps">{{ t('resources.timestamps') }}</n-checkbox><n-button @click="startLogs">{{ t('resources.reconnect') }}</n-button></div><p class="muted">{{ streaming?t('resources.streaming'):t('resources.streamInterrupted') }}</p><pre class="terminal" aria-live="polite">{{ logs||t('resources.waitingLogs') }}</pre></template><template v-else-if="tab==='terminal'"><div class="toolbar"><n-select filterable v-model:value="shell" :input-props="{'aria-label':t('resources.terminalShell')}" :options="[{label:'/bin/sh',value:'/bin/sh'},{label:'/bin/bash',value:'/bin/bash'}]"/><n-button @click="connectTerminal">{{ t('resources.connectTty') }}</n-button><n-button @click="ws?.close()">{{ t('resources.disconnect') }}</n-button></div><p v-if="terminalStatus" class="muted" role="status">{{ t(`resources.${terminalStatus}`) }}</p><pre class="terminal">{{ terminal||t('resources.terminalHint') }}</pre><form class="toolbar" @submit.prevent="sendCommand"><n-input v-model:value="command" :input-props="{'aria-label':t('resources.terminalCommand')}" :placeholder="t('resources.commandPlaceholder')"/><n-button attr-type="submit">{{ t('resources.send') }}</n-button><n-button @click="ws?.send('\u0003')">Ctrl+C</n-button></form></template><template v-else-if="tab==='stats'"><p class="inline-error">{{ message(resourceStats) }}</p><pre class="json-block">{{ pretty(stats) }}</pre></template><template v-else-if="tab==='config'"><div v-if="pretty(detail).includes('com.docker.compose.project')" class="notice">{{ t('resources.composeManaged') }}<n-button @click="emit('navigate','compose')">{{ t('resources.goCompose') }}</n-button></div><template v-else><p class="muted">{{ t('resources.configHint') }}</p><div class="tabs"><button :class="{active:configMode==='form'}" @click="configMode='form';preview=null">{{ t('resources.commonConfig') }}</button><button :class="{active:configMode==='json'}" @click="configMode='json';preview=null">{{ t('resources.advancedJson') }}</button></div><template v-if="configMode==='form'"><div v-for="f in configFields" :key="f.key" class="form-field"><n-checkbox :checked="Boolean(configEnabled[f.key])" @update:checked="configEnabled[f.key]=$event;preview=null">{{ t('resources.modifyField',{field:renderText(f.label)}) }}</n-checkbox><n-input :value="String(configValues[f.key]??'')" :disabled="!configEnabled[f.key]" :type="['env','cmd'].includes(f.key)?'textarea':'text'" :placeholder="renderText(f.hint)" :input-props="{'aria-label':renderText(f.label)}" @update:value="configValues[f.key]=$event;preview=null"/><small>{{ renderText(f.hint) }}</small></div></template><n-input class="code-editor" v-else v-model:value="configText" @update:value="preview=null" type="textarea" :autosize="{minRows:8}" :input-props="{'aria-label':t('resources.advancedConfigJson')}"/><div class="actions section-gap"><n-button @click="previewConfig">{{ t('resources.validatePreview') }}</n-button><n-button type="primary" :disabled="!preview" @click="applyConfig">{{ t('resources.confirmApply') }}</n-button></div><pre v-if="preview" class="json-block">{{ pretty(preview) }}</pre></template></template><template v-else><div v-if="kind==='images'" class="actions"><a class="file-button" :href="`/api/v1${base}/${encodeURIComponent(selected)}/export`">{{ t('resources.exportTar') }}</a></div><div v-if="kind==='volumes'&&Array.isArray(detail.containers)" class="section-gap"><h3>{{ t('resources.volumeContainers') }}</h3><div v-for="row in rows(detail.containers)" :key="ident(row)" class="snapshot-row"><button class="resource-name" @click="linkedResource('containers',ident(row))">{{ name(row) }} ↗</button><span class="tag">{{ displayState(state(row)) }}</span></div></div><div v-if="kind==='containers'&&tab==='data'"><h3>{{ t('resources.mountedData') }}</h3><div v-for="(mount,i) in rows(detail.Mounts)" :key="i" class="snapshot-row"><span>{{ str(mount.Source) }} → {{ str(mount.Destination) }}</span><button v-if="mount.Name" class="resource-name" @click="linkedResource('volumes',str(mount.Name))">{{ t('resources.viewVolume') }}</button></div></div><pre class="json-block">{{ pretty(tab==='data'?detail.Mounts??detail.mounts??detail:detail) }}</pre></template></div></n-drawer-content></n-drawer><FormDialog v-model:show="form" :title="formTitle" :fields="fields" :submit="submitForm" :description="formDescription" @saved="feedback=localized('resources.submitted');load()"/><ConfirmDialog v-model:show="confirm" :title="confirmTitle" :detail="confirmDetail" :error="error" :busy="actionBusy" @confirm="execute"/></template>
